import{_ as i,o as a,c as d,a2 as n}from"./chunks/framework.CgxQ0r6v.js";const h=JSON.parse('{"title":"Contenido Programático: Redes (Trayecto II)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Redes/Contenido_Programatico.md","filePath":"materias/Redes/Contenido_Programatico.md"}'),o={name:"materias/Redes/Contenido_Programatico.md"};function s(r,e,l,t,c,u){return a(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="contenido-programatico-redes-trayecto-ii" tabindex="-1">Contenido Programático: Redes (Trayecto II) <a class="header-anchor" href="#contenido-programatico-redes-trayecto-ii" aria-label="Permalink to &quot;Contenido Programático: Redes (Trayecto II)&quot;">​</a></h1><p><strong>Unidad Curricular:</strong> Redes <strong>Unidades Crédito:</strong> 6 <strong>Duración:</strong> 2 trimestres <strong>Código:</strong> RCT226</p><hr><h2 id="🔌-saberes" tabindex="-1">🔌 SABERES <a class="header-anchor" href="#🔌-saberes" aria-label="Permalink to &quot;🔌 SABERES&quot;">​</a></h2><h3 id="unidad-1-fundamentos-basicos-de-redes" tabindex="-1">Unidad 1: Fundamentos básicos de Redes <a class="header-anchor" href="#unidad-1-fundamentos-basicos-de-redes" aria-label="Permalink to &quot;Unidad 1: Fundamentos básicos de Redes&quot;">​</a></h3><ul><li>Concepto de redes.</li><li>Elementos: emisor, mensaje, medio y receptor.</li><li>Medios de Comunicación: Alámbricos (guiados) – Inalámbricos (no guiados).</li><li>Transmisión de datos: Unidades de transmisión, Medios, Formas: Serie y Paralelo.</li><li>Modos de transmisión de datos: simplex, Half-duplex, full-duplex.</li><li>Dirección IP, estructura, clases y mascara de red.</li></ul><h3 id="unidad-2-comunicacion" tabindex="-1">Unidad 2: Comunicación <a class="header-anchor" href="#unidad-2-comunicacion" aria-label="Permalink to &quot;Unidad 2: Comunicación&quot;">​</a></h3><ul><li>Líneas de Comunicación: Definición, Objetivos, Funciones y Clasificación: conmutadas, dedicadas, punto a punto, multipunto y digitales.</li><li>Medios de conexión de Redes: definición, objetivos y funciones.</li><li>Tipos de Medios: Cobre, fibra óptica e inalámbrica.</li><li>Tipo de cable: STP, UTP.</li><li>Conectores: Jack, RJ45.</li><li>Implementación del cableado con RJ45: Directos y Cruzados, aplicando el estándar EIA/TIA 568A - 568B.</li><li>Especificaciones de cables: velocidad, problemas inherentes: ruidos, atenuación y diafonía.</li></ul><h3 id="unidad-3-componentes-de-una-red-lan" tabindex="-1">Unidad 3: Componentes de una red LAN <a class="header-anchor" href="#unidad-3-componentes-de-una-red-lan" aria-label="Permalink to &quot;Unidad 3: Componentes de una red LAN&quot;">​</a></h3><ul><li>Tarjeta de Interfaz de red (Instalación y prueba).</li><li>Administración de sistemas operativos de redes (software libre y propietario).</li><li>Estaciones de trabajo.</li><li>Servidores.</li><li>Repetidora, bridges, routers, brouters, MAU (Multistation Access Unit), hubs y Switch Hub o Switch Ethernet.</li></ul><h3 id="unidad-4-redes-de-telecomunicaciones-y-de-datos" tabindex="-1">Unidad 4: Redes de Telecomunicaciones y de Datos <a class="header-anchor" href="#unidad-4-redes-de-telecomunicaciones-y-de-datos" aria-label="Permalink to &quot;Unidad 4: Redes de Telecomunicaciones y de Datos&quot;">​</a></h3><ul><li>Tipos de Redes: Redes Conmutadas, Redes de Difusión.</li><li>Topologías de redes físicas: Bus, Anillo, Estrella, Malla.</li><li>Nodos: Definición, objetivos principales.</li><li>Clasificación de Redes.</li><li>Clasificación por tecnología de transmisión.</li><li>Clasificación según su administración: públicas y privadas.</li><li>Clasificación según ubicación geográfica: LAN, MAN y WAN.</li></ul><h3 id="unidad-5-protocolos-de-redes" tabindex="-1">Unidad 5: Protocolos de Redes <a class="header-anchor" href="#unidad-5-protocolos-de-redes" aria-label="Permalink to &quot;Unidad 5: Protocolos de Redes&quot;">​</a></h3><ul><li>Modelo OSI (Capas: Física, Enlace, Red, Transporte, Sesión, Presentación y Aplicación).</li><li>Modelo TCP/IP (Capas: Interfaz de red, Internet, Transporte y Aplicación).</li><li>Modelo de comunicación: De par a par, encapsulamiento, Cliente/servidor. Dominios (colisión, broadcast). Segmento de red.</li></ul><h3 id="unidad-6-ancho-de-banda-y-tecnologias" tabindex="-1">Unidad 6: Ancho de Banda y Tecnologías <a class="header-anchor" href="#unidad-6-ancho-de-banda-y-tecnologias" aria-label="Permalink to &quot;Unidad 6: Ancho de Banda y Tecnologías&quot;">​</a></h3><ul><li>Ancho de banda: Concepto, características, medición, tasa de transferencia.</li><li>Tecnologías de redes: Token Ring, Ethernet, FDDI. Capas a las que pertenecen.</li></ul><h3 id="unidad-7-planeacion-de-una-red-lan" tabindex="-1">Unidad 7: Planeación de una red LAN <a class="header-anchor" href="#unidad-7-planeacion-de-una-red-lan" aria-label="Permalink to &quot;Unidad 7: Planeación de una red LAN&quot;">​</a></h3><ul><li>Diseño.</li><li>Instalación.</li></ul><h3 id="unidad-8-administracion-de-redes" tabindex="-1">Unidad 8: Administración de redes <a class="header-anchor" href="#unidad-8-administracion-de-redes" aria-label="Permalink to &quot;Unidad 8: Administración de redes&quot;">​</a></h3><ul><li>Configuración básica del protocolo TCP/IP, Tarjeta Red, Conexión Internet; Configuración de HW de red; Navegación en Internet.</li><li>Configuración de una LAN; Demonios y el superservidor de Internet (inetd, xinetd).</li><li>Servicios de acceso: Telnet / SSH; Servicios de transferencia de ficheros: FTP /SFTP/ SCP.</li><li>Servicio de resolución de nombres: DNS; Servicios de compartición de ficheros e impresoras: NFS, Samba; Servicio de correo: SMTP.</li><li>Servicios Web: HTTP (Apache); Servicio de news; Servicio de IRC.</li><li>Instalación de colas de trabajo: NQS.</li></ul><h3 id="unidad-9-seguridad" tabindex="-1">Unidad 9: Seguridad <a class="header-anchor" href="#unidad-9-seguridad" aria-label="Permalink to &quot;Unidad 9: Seguridad&quot;">​</a></h3><ul><li>Configuración de un Proxy.</li><li>Configuración de un firewall (ipchains, iptables).</li><li>Restricción de acceso a servicios (TCP_wrappers).</li><li>Identificación de usuarios mediante PAM.</li><li>Configuración de un servidor Kerberos; VPN&#39;s con IPsec.</li></ul><h3 id="unidad-10-principios-basicos-de-enrutamiento-y-subredes" tabindex="-1">Unidad 10: Principios básicos de enrutamiento y subredes <a class="header-anchor" href="#unidad-10-principios-basicos-de-enrutamiento-y-subredes" aria-label="Permalink to &quot;Unidad 10: Principios básicos de enrutamiento y subredes&quot;">​</a></h3><ul><li>Protocolo de redes: Protocolo enrutado. Protocolos de enrutamiento. Clases de direcciones IP de red.</li><li>Introducción y razones para realizar subredes.</li><li>Pruebas de Diseño de Redes: Diseño de Arquitectura de redes, instalación y configuración de topologías.</li><li>Diseño de interfaz de red.</li></ul><h3 id="unidad-11-ip-y-subredes" tabindex="-1">Unidad 11: IP y Subredes <a class="header-anchor" href="#unidad-11-ip-y-subredes" aria-label="Permalink to &quot;Unidad 11: IP y Subredes&quot;">​</a></h3><ul><li>Estructuración de IP en subredes.</li><li>IPv4: Generalidades, Clasificación, Ejemplos y Ejercicios.</li><li>IPv6: Generalidades y Clasificación.</li></ul><h3 id="unidad-12-estandares-de-transmision-de-datos" tabindex="-1">Unidad 12: Estándares de transmisión de datos <a class="header-anchor" href="#unidad-12-estandares-de-transmision-de-datos" aria-label="Permalink to &quot;Unidad 12: Estándares de transmisión de datos&quot;">​</a></h3><ul><li>Clasificación de los estándares.</li><li>Estándar 802.3 Definición, características y variantes.</li><li>Estándar 802.11 definición, características y variantes.</li></ul>',28)])])}const p=i(o,[["render",s]]);export{h as __pageData,p as default};
